sys_script_client.script:
function onSubmit() {

    var startTime = g_form.getValue('start_time');
    var endTime = g_form.getValue('end_time');

    if (!startTime || !endTime) {
        return true;
    }

    var start = startTime.split(':');
    var end = endTime.split(':');

    var startSeconds = 
        (parseInt(start[0], 10) * 3600) +
        (parseInt(start[1], 10) * 60) +
        parseInt(start[2], 10);

    var endSeconds =
        (parseInt(end[0], 10) * 3600) +
        (parseInt(end[1], 10) * 60) +
        parseInt(end[2], 10);

    if (endSeconds <= startSeconds) {

        g_form.addErrorMessage(
            'End Time must be after Start Time.'
        );

        return false;
    }

    return true;
}
